{'role': 'user', 'content': [{'tool_use_id': 'toolu_01YU7J7GZa57XL4hAoepAuq1', 'type': 'tool_result', 'content': '     1→import type { DeviceInfo } from "../../types";
     2→import { useBridgeStore } from "../../stores/bridgeStore";
     3→import { DeviceCard } from "./DeviceCard";
     4→
     5→export function DeviceList({
     6→  devices,
     7→}: {
     8→  devices: Record<string, DeviceInfo>;
     9→}) {
    10→  const entries = Object.entries(devices);
    11→  const isReceiving = useBridgeStore((s) => s.isReceiving);
    12→  const lastMessageAgeMs = useBridgeStore((s) => s.lastMessageAgeMs);
    13→  const routeCorrect = useBridgeStore((s) => s.routeCorrect);
    14→  const networkInterface = useBridgeStore((s) => s.networkInterface);
    15→
    16→  if (entries.length === 0) {
    17→    // Bridge is connected and sending data but beat-link hasn't announced any
    18→    // devices yet. Most likely cause: wrong broadcast route (169.254.255.255
    19→    // going out the wrong interface so Pioneer announcements can't reach the
    20→    // bridge). Also seen briefly after a route fix before beat-link re-probes.
    21→    //
    22→    // Note: USB-to-Ethernet adapters (en4, en5, en16, etc.) are handled the
    23→    // same as built-in ports — the route and interface selection matter, not
    24→    // the adapter type. If devices still don't appear after fixing the route,
    25→    // unplug and replug the adapter to trigger a fresh DHCP + link-local cycle.
    26→    //
    27→    // "recentTraffic" uses an 8-second grace window on top of isReceiving so
    28→    // the message doesn't flicker between "traffic detected" and "no devices"
    29→    // as Pioneer announcement bursts arrive — the watchdog pulses isReceiving
    30→    // true/false between bursts, but lastMessageAgeMs stays low while traffic
    31→    // is ongoing.
    32→    // lastMessageAgeMs is -1 when no Pioneer packet has ever been received.
    33→    // A non-negative value below 8 000 ms means traffic arrived recently.
    34→    const recentTraffic =
    35→      isReceiving || (lastMessageAgeMs >= 0 && lastMessageAgeMs < 8000);
    36→
    37→    if (recentTraffic) {
    38→      return (
    39→        <div className="rounded-lg border border-dashed border-yellow-900/50 px-4 py-5 text-center space-y-1.5">
    40→          <p className="text-sm text-yellow-500/80">
    41→            Pioneer traffic detected on{" "}
    42→            <span className="font-mono text-yellow-400">
    43→              {networkInterface ?? "unknown interface"}
    44→            </span>
    45→            , but no devices discovered yet.
    46→          </p>
    47→          <p className="text-xs text-gray-500">
    48→            {routeCorrect === false
    49→              ? "Route mismatch is likely the cause — fix the route above, then restart the bridge."
    50→              : "Waiting for beat-link device announcements. This usually resolves within a few seconds."}
    51→          </p>
    52→        </div>
    53→      );
    54→    }
    55→
    56→    return (
    57→      <div className="rounded-lg border border-dashed border-gray-700 px-4 py-6 text-center">
    58→        <p className="text-sm text-gray-500">
    59→          No Pioneer devices found
    60→          {networkInterface && (
    61→            <span className="text-gray-600">
    62→              {" "}on <span className="font-mono">{networkInterface}</span>
    63→            </span>
    64→          )}
    65→          .
    66→        </p>
    67→        <p className="text-xs text-gray-600 mt-1">
    68→          {routeCorrect === false
    69→            ? "Route mismatch detected — fix the route above, then restart the bridge."
    70→            : "Check cable, interface selection, and route status above."}
    71→        </p>
    72→      </div>
    73→    );
    74→  }
    75→
    76→  return (
    77→    <div className="space-y-2">
    78→      <h3 className="text-xs font-medium uppercase tracking-wide text-gray-500">
    79→        Devices ({entries.length})
    80→      </h3>
    81→      {entries.map(([ip, device]) => (
    82→        <DeviceCard key={ip} ip={ip} device={device} />
    83→      ))}
    84→    </div>
    85→  );
    86→}
    87→'}]}

